# autopilot-wrapper: generated by autopilot-setup; set-docs regenerates it.
"""Windows codex_command for ralphex (called through codex-agrouter.cmd).

Routes Codex runs through agrouter. ralphex calls `<codex_command> exec <codex options>`
with the prompt on stdin; agrouter emits codex's own `exec`, so the leading one is dropped.
--doc files feed agrouter's project-complexity stage only; codex never sees them.
"""
from pathlib import Path
import os
import shutil
import subprocess
import sys

ROOT = Path(__file__).resolve().parents[2]
DOCS = []      # project docs, relative to the repository root
DOC_DIRS = []  # every *.md in these directories is added too

docs = [ROOT / d for d in DOCS]
for folder in DOC_DIRS:
    docs += sorted((ROOT / folder).glob('*.md'))
args = sys.argv[1:]
if args[:1] == ['exec']:
    args = args[1:]
command = shutil.which('agrouter') or 'agrouter'
cmd = [command, 'exec', 'codex', *[f'--doc={d}' for d in docs], '--', *args]
sys.exit(subprocess.call(cmd, shell=os.name == 'nt' and Path(command).suffix.lower() in ('.cmd', '.bat')))
